C1=np.array([[1,3],[0,2]],dtype=int);C2=np.array([[1,0],[3,2]],dtype=int)
ne=[]
for i in range(2):
    for j in range(2):
        if C1[i,j]==min(C1[:,j]) and C2[i,j]==min(C2[i,:]):ne.append((i,j))
print('行/列0合作1争抢，甲乙代价矩阵:',C1,C2)
print('各列甲响应/各行乙响应:',np.argmin(C1,axis=0),np.argmin(C2,axis=1))
print('纯NE索引:',ne,'NE代价:',[(C1[i,j],C2[i,j]) for i,j in ne])
print('同时合作代价:',C1[0,0],C2[0,0],'甲单方争抢后:',C1[1,0])
